<?php declare(strict_types=1); require_once __DIR__ . '/db.php';  if ($_SERVER['REQUEST_METHOD'] !== 'POST') {     header('Location: apply.php');     exit; }  $name = trim($_POST['full_name'] ?? ''); $email = trim($_POST['email'] ?? ''); $phone = trim($_POST['phone'] ?? ''); $courseId = filter_input(INPUT_POST, 'course_id', FILTER_VALIDATE_INT); $statement = trim($_POST['statement'] ?? '');  $errors = []; if ($name === '' || mb_strlen($name) > 120) $errors[] = 'Enter a name of up to 120 characters.'; if (!filter_var($email, FILTER_VALIDATE_EMAIL) || strlen($email) > 190) $errors[] = 'Enter a valid email address.'; if ($phone === '' || mb_strlen($phone) > 30) $errors[] = 'Enter a valid phone number.'; if (!$courseId || $courseId < 1) $errors[] = 'Choose a valid course.'; if (mb_strlen($statement) > 2000) $errors[] = 'The statement is too long.';  if (!$errors) {     $check = $pdo->prepare('SELECT course_id FROM courses WHERE course_id = ?');     $check->execute([$courseId]);     if (!$check->fetch()) $errors[] = 'The selected course does not exist.'; }  if ($errors) {     http_response_code(400);     echo '<!doctype html><html lang="en"><meta charset="utf-8"><title>Check application</title><body>';     echo '<h1>Please correct the following</h1><ul>';     foreach ($errors as $error) {         echo '<li>' . htmlspecialchars($error, ENT_QUOTES, 'UTF-8') . '</li>';     }     echo '</ul><p><a href="apply.php">Return to application form</a></p></body></html>';     exit; }  $stmt = $pdo->prepare(   'INSERT INTO applications (full_name, email, phone, course_id, statement)    VALUES (:name, :email, :phone, :course_id, :statement)' ); $stmt->execute([   'name' => $name,   'email' => $email,   'phone' => $phone,   'course_id' => $courseId,   'statement' => $statement === '' ? null : $statement ]); ?> <!doctype html> <html lang="en"><head><meta charset="utf-8"><title>Application received</title></head> <body>   <h1>Application received</h1>   <p>Thank you, <?= htmlspecialchars($name, ENT_QUOTES, 'UTF-8') ?>. Your application has been saved.</p>   <p><a href="index.php">Return to homepage</a></p> </body></html> 